Sanitización.ejemplo:
// Sanitización segura de HTML enriquecido en navegador con DOMPurify
import DOMPurify from 'dompurify';

const dirtyHtml = '<p>Hola <img src=x onerror=alert(1)><a href="javascript:evil()">link</a></p>';
const cleanHtml = DOMPurify.sanitize(dirtyHtml, {
  ALLOWED_TAGS: ['p', 'b', 'i', 'a'],
  ALLOWED_ATTR: ['href']
});
// Resultado: '<p>Hola <a>link</a></p>'

Template injection.ejemplo:
# Vulnerable (Jinja2 SSTI -> RCE)
from flask import render_template_string, request
@app.route("/hello")
def hello():
    name = request.args.get("name", "")
    return render_template_string(f"<h1>Hola {name}</h1>")

# Seguro: pasar la entrada como parámetro de contexto
return render_template_string("<h1>Hola {{ name }}</h1>", name=name)

